import{_ as e,o as r,c as t,x as i}from"./chunks/framework.DzQQ_lrg.js";const o="/xi-kari-skill/handbook/images/representation.svg",m=JSON.parse('{"title":"平均数准确，为什么仍看不见局部过载","description":"数据是否足够，取决于你到底要回答什么问题。","frontmatter":{"title":"平均数准确，为什么仍看不见局部过载","description":"数据是否足够，取决于你到底要回答什么问题。"},"headers":[],"relativePath":"concepts/representation.md","filePath":"concepts/representation.md"}'),l={name:"concepts/representation.md"};function n(s,a,h,c,p,d){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="平均数准确-为什么仍看不见局部过载" tabindex="-1">平均数准确，为什么仍看不见局部过载 <a class="header-anchor" href="#平均数准确-为什么仍看不见局部过载" aria-label="Permalink to &quot;平均数准确，为什么仍看不见局部过载&quot;">​</a></h1><p>同样平均排队10件，现场真的一样吗？</p><p><strong>数据是否足够，取决于你到底要回答什么问题。</strong></p><h2 id="从具体情景看区别" tabindex="-1">从具体情景看区别 <a class="header-anchor" href="#从具体情景看区别" aria-label="Permalink to &quot;从具体情景看区别&quot;">​</a></h2><p>原文设定两个队列，超过15件就算某个位置过载。一个状态是第一处0件、第二处20件，另一个状态是两处各10件；二者的平均数都是10，局部过载的答案却不同。如果只保存平均数，后来再聪明的规则也不能从这个共同数字里还原被折叠的区别。平均数并没有算错：它仍能回答平均量和总量。</p><p>问题是用途变成了识别局部过载。原文接着加入最大值，这足以回答是否过载以及最大长度，却仍不知道哪个位置较大；遇到两个位置服务能力不同，位置又成为必要信息。因此，改进表示可以只补上当前问题需要的区别，不必恢复所有细节；也不能因为一个任务答得好，就宣布同一表示能够回答所有任务。</p><figure class="concept-figure"><img src="'+o+'" alt="相同平均数，两个不同答案"><figcaption>平均数保留了总量信息，却将本题所需的局部分布折叠了。</figcaption></figure><h2 id="对照真实案例-区别还在-单位没有对上" tabindex="-1">对照真实案例：区别还在，单位没有对上 <a class="header-anchor" href="#对照真实案例-区别还在-单位没有对上" aria-label="Permalink to &quot;对照真实案例：区别还在，单位没有对上&quot;">​</a></h2><p>平均数把(0,20)和(10,10)折成同一个10，事后怎样换算都分不开。火星气候轨道器的单位错误不属于这一类。NASA调查报告记载：接口规范要求地面软件以牛顿秒输出，实际输出是磅力秒，两者之间的换算因子是4.45；单位查明之后，导航估算改用修正后的数值重算了轨道。也就是说，不同的冲量在文件里仍是不同的数，错在实际输出没有遵守规范。<a href="https://llis.nasa.gov/llis_lib/pdf/1009464main1_0641-mr.pdf" target="_blank" rel="noreferrer">NASA第一阶段调查报告，第14、16页</a></p><p>原文<a href="/xi-kari-skill/handbook/theory/appendix-c.html#section-c-7">附录C.7</a>把表示是否充分与实际执行是否正确分开检验，本页把这个单位错误读作后一类。<a href="/xi-kari-skill/handbook/cases/mars-climate-orbiter.html">阅读案例：火星气候轨道器</a></p><h2 id="真实材料-预报锥画的是中心路径-不是潮水范围" tabindex="-1">真实材料：预报锥画的是中心路径，不是潮水范围 <a class="header-anchor" href="#真实材料-预报锥画的是中心路径-不是潮水范围" aria-label="Permalink to &quot;真实材料：预报锥画的是中心路径，不是潮水范围&quot;">​</a></h2><p>美国国家飓风中心（NHC）的预报锥是一种写明了用途的表示：按2022年的定义，它表示热带气旋中心的可能路径，圆的大小使此前五年的官方预报误差有三分之二落在圆内。<a href="https://web.archive.org/web/20220926140803/https://www.nhc.noaa.gov/aboutcone.shtml" target="_blank" rel="noreferrer">NHC预报锥定义，2022年9月26日存档</a> 2022年飓风伊恩在佛罗里达州西南部登陆后，NHC的事后报告称，所有预报周期的预报锥都包含了登陆位置。同一份报告也记录，Fort Myers Beach的传感器测到高出平均高高潮位12.70英尺的水位，不到30英里外的Pirate Harbor只有4.47英尺；报告认为这类差别显示了风暴潮对风暴确切路径的敏感。<a href="https://www.nhc.noaa.gov/data/tcr/AL092022_Ian.pdf" target="_blank" rel="noreferrer">NHC伊恩飓风报告，第8—9、15—16页</a></p><p>预报锥要回答的是“中心大概去哪里”。某一段海岸的潮水会有多高是另一个问题，预报锥的定义里没有这项信息，正如平均数里没有哪一处过载的信息；NHC另发风暴潮监视、警告和峰值预报来回答它。这份材料帮助辨认一种表示是为哪个问题而做，它不是对原文形式命题的检验。</p><p><a href="/xi-kari-skill/handbook/cases/representation-hurricane-cone.html">阅读伊恩飓风案例：来源、数字与适用范围</a></p><p>Optional, same file, last item of the list under <code>## 接着理解</code> (same form as the existing orbiter entry there):</p><ul><li><a href="./../cases/representation-hurricane-cone.html">真实案例 · 飓风伊恩的预报锥：回答的是中心路径</a></li></ul><h2 id="回到原文" tabindex="-1">回到原文 <a class="header-anchor" href="#回到原文" aria-label="Permalink to &quot;回到原文&quot;">​</a></h2><blockquote><p>总量表示可准确回答总量，增加一个与任务相关的变量可修复部分不足</p></blockquote><ul><li><a href="/xi-kari-skill/handbook/theory/appendix-c.html#section-c-9">附录C.9 双队列的任务差异</a></li><li><a href="/xi-kari-skill/handbook/theory/appendix-c.html#section-c-6">附录C.6 F1任务恢复与最坏误差</a></li></ul><h2 id="这处区别能说明到哪里" tabindex="-1">这处区别能说明到哪里 <a class="header-anchor" href="#这处区别能说明到哪里" aria-label="Permalink to &quot;这处区别能说明到哪里&quot;">​</a></h2><p>双队列及阈值是原文人工模型。其961个等概率状态和错误率不是现实队列分布。补入最大值后的充分性，也不能直接推广到更多队列或不同动力条件。</p><h2 id="接着理解" tabindex="-1">接着理解 <a class="header-anchor" href="#接着理解" aria-label="Permalink to &quot;接着理解&quot;">​</a></h2><ul><li><a href="./prediction.html">能预测常态，为什么未必能预测改变后的结果</a></li><li><a href="./joint-feasibility.html">每件事都做得到，为什么放在一起就做不到</a></li><li><a href="./../cases/mars-climate-orbiter.html">真实案例 · 火星气候轨道器：接口的单位差异</a></li></ul>',23)])])}const b=e(l,[["render",n]]);export{m as __pageData,b as default};
